// components/Process.tsx
const steps = [
  { title: "Submit Survey Request", desc: "Fill out our simple online form with your project details." },
  { title: "Team Reviews & Confirms", desc: "Our team reviews your request and provides accurate pricing." },
  { title: "Survey Execution", desc: "Professional surveyors visit your site with modern instruments." },
  { title: "Final Plans & Handover", desc: "Receive accurate survey plans and legal documents." }
];

export default function Process() {
  return (
    <section className="bg-gray-100 py-20 px-6">
      <h2 className="text-center text-3xl font-bold mb-12">How it Works</h2>
      <div className="max-w-5xl mx-auto grid grid-cols-1 md:grid-cols-4 gap-6">
        {steps.map((step, i) => (
          <div key={i} className="bg-white p-6 rounded-lg">
            <span className="text-brown-600 font-bold text-xl">0{i+1}</span>
            <h4 className="font-bold mt-2">{step.title}</h4>
            <p className="text-sm text-gray-600 mt-2">{step.desc}</p>
          </div>
        ))}
      </div>
    </section>
  );
}